String _img(String seed, String link) {
  final l = link.trim();
  if (l.isEmpty) return 'https://picsum.photos/seed/$seed/700/700';
  return _fixLink(l);
}

String _fixLink(String url) {
  final drive = RegExp(r'drive\.google\.com/file/d/([^/]+)').firstMatch(url);
  if (drive != null) {
    return 'https://drive.google.com/uc?export=view&id=${drive.group(1)}';
  }
  final open = RegExp(r'drive\.google\.com/open\?id=([^&]+)').firstMatch(url);
  if (open != null) {
    return 'https://drive.google.com/uc?export=view&id=${open.group(1)}';
  }
  return url;
}

